CREATE TABLE `Accounts` (`account_id` DECIMAL(18,2), `customer_id` DECIMAL(18,2), `account_name` VARCHAR(100), `other_account_details` VARCHAR(100));
CREATE TABLE `Customers` (`customer_id` DECIMAL(18,2), `customer_first_name` VARCHAR(100), `customer_last_name` VARCHAR(100), `customer_address` VARCHAR(100), `customer_phone` VARCHAR(100), `customer_email` VARCHAR(100), `other_customer_details` VARCHAR(100));
CREATE TABLE `Customers_Cards` (`card_id` DECIMAL(18,2), `customer_id` DECIMAL(18,2), `card_type_code` VARCHAR(100), `card_number` VARCHAR(100), `date_valid_from` DATETIME, `date_valid_to` DATETIME, `other_card_details` VARCHAR(100));
CREATE TABLE `Financial_Transactions` (`transaction_id` DECIMAL(18,2), `previous_transaction_id` DECIMAL(18,2), `account_id` DECIMAL(18,2), `card_id` DECIMAL(18,2), `transaction_type` VARCHAR(100), `transaction_date` DATETIME, `transaction_amount` DECIMAL(18,2), `transaction_comment` VARCHAR(100), `other_transaction_details` VARCHAR(100));
